<?php
declare(strict_types=1);
include __DIR__ . '/../Shared/member-desktop.css.php';
include __DIR__ . '/../Shared/member-desktop-header.php';

$basePath=rtrim((string)config('app.base_path'),'/');
$bookings=is_array($bookings??null)?$bookings:[];
$restaurantOrders=is_array($restaurantOrders??null)?$restaurantOrders:[];
$freshFoodOrders=is_array($freshFoodOrders??null)?$freshFoodOrders:[];
$commercialRentalBookings=is_array($commercialRentalBookings??null)?$commercialRentalBookings:[];
function maBe(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function maBm(mixed $v):string{return '₹'.number_format((float)$v,2);}
function maDt(?string $v,string $fallback=''):string{if(!$v)return $fallback;try{return (new DateTime($v))->format('d M Y · h:i A');}catch(Throwable){return $v;}}
$restaurantPast=['COMPLETED','CANCELLED','REJECTED'];
$freshPast=['COMPLETED','CANCELLED','REJECTED'];
$combined=[];
foreach($bookings as $b){$status=(string)($b['status']??'Pending');$combined[]=['kind'=>'taxi','past'=>in_array($status,['Completed','Cancelled','No Show'],true),'created_at'=>$b['created_at']??null,'record'=>$b];}
foreach($restaurantOrders as $o){$status=strtoupper((string)($o['status']??'PENDING'));$combined[]=['kind'=>'restaurant','past'=>in_array($status,$restaurantPast,true),'created_at'=>$o['created_at']??null,'record'=>$o];}
foreach($freshFoodOrders as $o){$status=strtoupper((string)($o['status']??'PENDING'));$combined[]=['kind'=>'fresh_food','past'=>in_array($status,$freshPast,true),'created_at'=>$o['created_at']??null,'record'=>$o];}
foreach($commercialRentalBookings as $o){$status=strtoupper((string)($o['status']??'REQUESTED'));$combined[]=['kind'=>'commercial_rental','past'=>in_array($status,['COMPLETED','CANCELLED','REJECTED'],true),'created_at'=>$o['created_at']??null,'record'=>$o];}
usort($combined,static function(array $a,array $b):int{return strcmp((string)($b['created_at']??''),(string)($a['created_at']??''));});
$upcomingCount=count(array_filter($combined,static fn(array $e):bool=>!$e['past']));
$pastCount=count($combined)-$upcomingCount;
$kindLabels=['taxi'=>'Rides','restaurant'=>'Food','fresh_food'=>'Fresh','commercial_rental'=>'Rental'];
?>
