<script>
(()=>{
let currentKind='upcoming',currentService='all';
const cards=[...document.querySelectorAll('.booking-card')],heading=document.getElementById('bookingHeading'),countEl=document.getElementById('bookingCount');
function applyFilters(){let shown=0;cards.forEach(c=>{const okKind=c.dataset.kind===currentKind;const okService=currentService==='all'||c.dataset.service===currentService;const show=okKind&&okService;c.classList.toggle('is-hidden',!show);if(show)shown++;});if(heading)heading.textContent=currentKind==='upcoming'?'Upcoming':'Past';if(countEl)countEl.textContent=shown+' booking'+(shown===1?'':'s');}
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(x=>x.classList.remove('active'));b.classList.add('active');currentKind=b.dataset.filter;applyFilters();}));
document.querySelectorAll('[data-service-filter]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-service-filter]').forEach(x=>x.classList.remove('active'));b.classList.add('active');currentService=b.dataset.serviceFilter;applyFilters();}));
applyFilters();
})();
</script>
